            2'b01: begin out <= 1'b1; if (k) state <= 2'b10; else state <= 2'b00; end
            2'b10: begin out <= 1'b1; if (k) state <= 2'b11; else state <= 2'b01; end
            2'b11: begin out <= 1'b0; if (j) state <= 2'b00; else state <= 2'b10; end
        endcase
    end
endmodule

// Moore state machine, two inputs, one output.
module TopModule(
    input  clk,
    input  areset,
    input  j,
    input  k,
    output reg out
);
    // State encoding: OFF=0, ON=1.
    reg [1:0] state, next_state;
    always @(*) begin
        case (state)
            2'b00: next_state = (j) ? 2'b01 : 2'b00;
            2'b01: next_state = (k) ? 2'b10 : 2'b01;
            2'b10: next_state = (k) ? 2'b10 : 2'b00;
            2'b11: next_state = (j) ? 2'b01 : 2'b00;
            default: next_state = 2'b00;
        endcase
    end
    always @(posedge clk) begin
        if (areset) state <= 2'b00;
        else state <= next_state;
    end
    always @(*) out = (state == 2'b01);
endmodule

